auto Performance::morph(float position)  -> bool{
  if(!(position>=0 && position<=1)) return false;
  if(mode_==UiMode::Perform && performance_page_==3)return mutation_set(track_const(selected_).mutation.seed,unsigned(position*100+0.5f),false);
  if(control_all_){Command c{CommandType::SetControlAll,0,0,1};c.scalar=(position-0.5f)*2;c.parameter=control_all_parameter_;if(!send(c))return false;control_all_position_=position;dirty_=true;return true;}
  // A factory/empty project can have identical A and B snapshots. Make the
  // first strip gesture audible while keeping all changes inside safe ranges.
  bool seed=morph_snapshots_equal(project_);
  if(seed){
   if(!engine_.morph_stage_ready(0) || !engine_.morph_stage_ready(1) || engine_.command_space()<4)return false;
   if(!store_morph(0))return false;
   for(unsigned t=0;t<kTracks;++t){
    auto& a=project_.morph_a[t];auto& b=project_.morph_b[t];b=a;
    b.values[morph_index(1)]=a.values[morph_index(1)]*0.85f;
    b.values[morph_index(3)]=a.values[morph_index(3)]>0.25f?0.25f:a.values[morph_index(3)];
    b.values[morph_index(4)]=a.values[morph_index(4)]<0.12f?0.12f:a.values[morph_index(4)];
    b.values[morph_index(5)]=a.values[morph_index(5)]<0.18f?0.18f:a.values[morph_index(5)];
    b.values[morph_index(10)]=a.values[morph_index(10)]<0.12f?0.12f:a.values[morph_index(10)];
    b.values[morph_index(64)]=a.values[morph_index(64)]<0.15f?0.15f:a.values[morph_index(64)];
   }
   if(!engine_.stage_morph(1,project_.morph_b))return false;
  }
  if(!project_.morph_enabled) {
   if(!send({CommandType::SetMorphEnabled,0,0,1})) return false;
   project_.morph_enabled=true;
  }
  Command c{CommandType::SetMorph,0,0,0}; c.scalar=position; if(!send(c)) return false; project_.morph_position=position; dirty_=true; return true;
 }
auto Performance::store_morph(unsigned side)  -> bool{
  if(side>1 || !engine_.morph_stage_ready(side) || !engine_.command_space())return false;
  for(unsigned t=0;t<16;++t)capture_parameter_snapshot(side?project_.morph_b[t]:project_.morph_a[t],project_,t);
  if(!engine_.stage_morph(side,side?project_.morph_b:project_.morph_a))return false;
  dirty_=true; return true;
 }
